// ═══════════════════════════════════════════════════════════════
// UTILITIES
// ═══════════════════════════════════════════════════════════════
function toTitleCase(s) { return s.replace(/\b\w/g, c => c.toUpperCase()); }
function toRoman(n) { return ['','I','II','III','IV','V','VI','VII','VIII','IX','X'][n] || String(n); }

function itemLabel(item) {
  return toTitleCase(item.replace(/^.*:/, '').replace(/_/g, ' '));
}
function statTypeLabel(st) {
  const map = {
    'tconstruct:head':'Head','tconstruct:handle':'Handle','tconstruct:binding':'Binding',
    'tconstruct:limb':'Bow Limb','tconstruct:bowstring':'Bowstring','tconstruct:grip':'Grip',
    'tconstruct:plating_helmet':'Helmet Plating','tconstruct:plating_chestplate':'Chestplate Plating',
    'tconstruct:plating_leggings':'Leggings Plating','tconstruct:plating_boots':'Boots Plating',
    'tconstruct:maille':'Maille','tconstruct:cuirass':'Cuirass',
  };
  return map[st] || toTitleCase(st.replace(/^.*:/, '').replace(/_/g, ' '));
}

